//! Bundled Certificate Transparency log table — ph3-tls-hardening A4, COMPAT-TRUST-CTLOGS.
//!
//! A CT log's identity is the SHA-256 hash of its public key (`LogID`, RFC 6962 §3.2 — the
//! same 32 bytes an SCT carries). For every log this build trusts the table holds the
//! operator, the log's `SubjectPublicKeyInfo` (to check the SCT signature, see
//! [`super::ct_sig`]) and its state. The data is [`super::ct_logs_data`], generated by
//! `scripts/gen_ct_logs.py` from two lists:
//!
//! * Google's `log_list.json` v3 (the list Chrome ships) — public logs, their operators
//!   and states;
//! * Yandex's `ctlog.json` — the six logs of the Russian national CA ecosystem (VK, Yandex,
//!   the Ministry of Digital Development), which Google's list does not carry.
//!
//! The generator refuses to write the table unless `log_id == SHA-256(key)` for every
//! entry and Google's keys agree with Apple's independent list. The unit tests here repeat
//! the first check on the compiled table, so a hand-edit of the generated file fails CI.
//!
//! The table is a curated trust decision that changes over time (logs get retired, new
//! shards open): refresh it by re-running the generator, never by editing the data file.

use std::sync::OnceLock;

use sha2::{Digest, Sha256};

/// What a log's state means for counting an SCT it issued (Chrome's CT policy, simplified).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum LogState {
    /// Accepting submissions (`usable` / `qualified` in the list): its SCTs count.
    Usable,
    /// No longer accepting submissions, but every SCT it issued stays valid.
    ReadOnly,
    /// Retired at `at_ms` (Unix ms): only SCTs stamped before that moment count.
    Retired {
        /// Retirement time, milliseconds since the Unix epoch.
        at_ms: u64,
    },
}

/// A table row as generated: strings only, decoded once into [`CtLog`].
pub(super) struct RawLog {
    pub operator: &'static str,
    pub name: &'static str,
    pub state: LogState,
    pub id_hex: &'static str,
    pub spki_hex: &'static str,
}

/// A CT log this build recognizes.
#[derive(Debug)]
pub struct CtLog {
    /// Who runs the log. Two SCTs from the same operator count once ([`super::ct`]).
    pub operator: &'static str,
    /// The log's description from the source list (diagnostics only).
    pub name: &'static str,
    /// Whether, and until when, its SCTs count.
    pub state: LogState,
    /// `LogID`: SHA-256 of [`Self::spki`].
    pub id: [u8; 32],
    /// The log's `SubjectPublicKeyInfo` DER.
    pub spki: Vec<u8>,
}

impl CtLog {
    /// Whether an SCT stamped at `timestamp_ms` still counts for this log.
    pub fn accepts_sct_at(&self, timestamp_ms: u64) -> bool {
        match self.state {
            LogState::Usable | LogState::ReadOnly => true,
            LogState::Retired { at_ms } => timestamp_ms < at_ms,
        }
    }
}

/// Decode a lowercase-hex string; `None` on odd length or a non-hex digit.
fn decode_hex(s: &str) -> Option<Vec<u8>> {
    if !s.len().is_multiple_of(2) {
        return None;
    }
    s.as_bytes()
        .chunks(2)
        .map(|pair| Some((hex_digit(pair[0])? << 4) | hex_digit(pair[1])?))
        .collect()
}

/// The value of one hex digit.
fn hex_digit(b: u8) -> Option<u8> {
    match b {
        b'0'..=b'9' => Some(b - b'0'),
        b'a'..=b'f' => Some(b - b'a' + 10),
        b'A'..=b'F' => Some(b - b'A' + 10),
        _ => None,
    }
}

/// Decode one generated row. A row whose id is not the hash of its key is dropped rather
/// than trusted: the table must never let an SCT claim a log it cannot be verified against.
fn decode(raw: &RawLog) -> Option<CtLog> {
    let spki = decode_hex(raw.spki_hex)?;
    let id: [u8; 32] = decode_hex(raw.id_hex)?.try_into().ok()?;
    (Sha256::digest(&spki)[..] == id).then_some(CtLog {
        operator: raw.operator,
        name: raw.name,
        state: raw.state,
        id,
        spki,
    })
}

/// Every log this build recognizes, decoded on first use.
pub fn all() -> &'static [CtLog] {
    static TABLE: OnceLock<Vec<CtLog>> = OnceLock::new();
    TABLE.get_or_init(|| super::ct_logs_data::RAW_LOGS.iter().filter_map(decode).collect())
}

/// The recognized log with this `LogID`, if any.
pub fn find(log_id: &[u8; 32]) -> Option<&'static CtLog> {
    all().iter().find(|log| &log.id == log_id)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_generated_row_decodes_and_its_id_is_the_key_hash() {
        assert_eq!(all().len(), super::super::ct_logs_data::RAW_LOGS.len());
    }

    #[test]
    fn log_ids_are_unique() {
        let mut ids: Vec<_> = all().iter().map(|l| l.id).collect();
        ids.sort_unstable();
        ids.dedup();
        assert_eq!(ids.len(), all().len());
    }

    #[test]
    fn a_row_with_a_foreign_id_is_dropped() {
        let good = &super::super::ct_logs_data::RAW_LOGS[0];
        let forged = RawLog {
            operator: good.operator,
            name: good.name,
            state: good.state,
            id_hex: "00".repeat(32).leak(),
            spki_hex: good.spki_hex,
        };
        assert!(decode(&forged).is_none());
        assert!(decode(good).is_some());
    }

    #[test]
    fn russian_ca_logs_are_known_with_three_operators() {
        let operators: std::collections::BTreeSet<_> = all()
            .iter()
            .filter(|l| l.name.contains("Yandex") || l.name.contains("VK") || l.name.contains("Ministry"))
            .map(|l| l.operator)
            .collect();
        assert_eq!(operators.len(), 3, "{operators:?}");
    }

    #[test]
    fn google_operator_is_present() {
        assert!(all().iter().any(|l| l.operator == "Google"));
    }

    #[test]
    fn retired_log_counts_only_sct_stamped_before_retirement() {
        let log = CtLog {
            operator: "X",
            name: "x",
            state: LogState::Retired { at_ms: 1_000 },
            id: [0; 32],
            spki: Vec::new(),
        };
        assert!(log.accepts_sct_at(999));
        assert!(!log.accepts_sct_at(1_000));
    }
}
